function getObj_nInfoEx(local=document, obj) {  
     var igetObj_nInfonfo_pp=document;
     if(local){  igetObj_nInfonfo_pp=local;   }
const igetObj_nInfonfo = { element: null,innerHTML: "",innerText: "",onclickProperty: function(){} };
  if(obj){
     if (obj.text && obj.text!="") {  
   const sdbutton = igetObj_nInfonfo_pp.querySelector(""+obj.text+"");
    if (!sdbutton) {        return igetObj_nInfonfo;    }
     const new_igetObj_nInfonfo = {
        element: sdbutton || null,
        innerHTML: sdbutton.innerHTML || "",
        innerText: sdbutton.innerText || sdbutton.textContent || "",
        onclickProperty: sdbutton.onclick || function(){},
    };    return new_igetObj_nInfonfo;
}    }   else {   return igetObj_nInfonfo;  }   }




function loaded_listff(tpe, lang, options) {
    var result = "";
    if (!tpe || tpe === "") {        return result;    }

    if (tpe === "skin") {
        return { class: "card", class_b: "page-link", class_icon: "svg" };
    }   else if (tpe === "routes") {
        return set_itend_cd[tpe];
    }
         
    if (!lang || lang === "") {        return result;    }

    if (set_itend_cd && set_itend_cd[tpe] && set_itend_cd[tpe][lang]) {
        result = set_itend_cd[tpe][lang];

        if (tpe === "sidebar" && options) {
  for (var fdi = 0; fdi < options.length; fdi++) {
        if (options[fdi].title && options[fdi].desc && options[fdi].icon && typeof options[fdi].open === "function") {
            result.push({
                label: options[fdi].title,
                desc: options[fdi].desc,
                icon: options[fdi].icon,
                onClick: options[fdi].open
            });
        }
    }
        }
    }

return result;    }







